const input = $input.first().json;
let body = input.body;

if (typeof body === 'string') {
    try {
        body = JSON.parse(body);
    } catch (e) {
        if (body.includes('=')) {
            try {
                const params = {};
                body.split('&').forEach(part => {
                    const [k, v] = part.split('=');
                    params[decodeURIComponent(k)] = decodeURIComponent(v);
                });
                body = params;
            } catch (err) {}
        }
    }
}

const userQuestion = body?.question || input.query?.question || input.question || '';
const question = userQuestion || 'Provide a health and security report for all servers';

// Detect query intent
function detectIntent(text) {
    const lowerText = text.toLowerCase();
    if (lowerText.includes('security') || lowerText.includes('threat') || lowerText.includes('risk')) {
        return 'SECURITY_REPORT';
    }
    return 'HEALTH_REPORT';
}

const reqServer = body?.server_name || input.query?.server_name || input.server_name;
const serverName = reqServer || 'all';

return [{
    json: {
        original_question: question,
        intent: detectIntent(question),
        server_name: serverName,
        timestamp: new Date().toISOString()
    }
}];

const originalQuestion = $('Process Question').first().json.original_question || 'Health Report';

// If the query is from the frontend telemetry poll, return the raw telemetry array as the report
if (originalQuestion.includes('Show Server Health Report') || originalQuestion.includes('telemetry')) {
    const rawTelemetry = $('Generate Server Telemetry').all().map(item => item.json);
    return [{
        json: {
            success: true,
            timestamp: new Date().toISOString(),
            question: originalQuestion,
            report: rawTelemetry,
            report_length: rawTelemetry.length,
            status: 'COMPLETE'
        }
    }];
}

// Otherwise, return the conversational LLM report
const aiResponse = $input.first().json.output || $input.first().json;
const response = {
    success: true,
    timestamp: new Date().toISOString(),
    question: originalQuestion,
    report: aiResponse,
    report_length: JSON.stringify(aiResponse).length,
    status: 'COMPLETE'
};

return [{ json: response }];
